// swift-tools-version:6.0
// A throwaway consumer package, generated by tools/verify-consumer/ios.sh outside the repository.
// It depends on the SDK by URL at exactly one version, as an app's Package.swift or Xcode project
// does, so the manifest at that tag, its products and its target paths are what is built: a
// checkout of this repository would prove the sources, not what a consumer resolves.
import PackageDescription

let package = Package(
    name: "VerifyConsumer",
    // The SDK's own floor (Package.swift at the repository root): a lower one here would make
    // SwiftPM refuse to resolve, which is the error an app with an older floor would see.
    platforms: [.iOS("17.4")],
    products: [
        .library(name: "VerifyConsumer", targets: ["VerifyConsumer"]),
    ],
    dependencies: [
        .package(url: "@REPO_URL@", exact: "@VERSION@"),
    ],
    targets: [
        .target(
            name: "VerifyConsumer",
            dependencies: [
                // The product an app adds. The Swift module it exports is OAuthClient. SwiftPM names the
                // package by the last path component of its URL.
                .product(name: "VersolaOAuth", package: "@REPO_NAME@"),
            ],
            swiftSettings: [.swiftLanguageMode(.v6)]
        ),
    ]
)
